function createBaseUserVoteInfo(): UserVoteInfo {
  return { hasVoted: false, voteOptionIndex: 0, voteOptionList: [] };
}

export const UserVoteInfo: MessageFns<UserVoteInfo> = {
  encode(message: UserVoteInfo, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.hasVoted !== false) {
      writer.uint32(8).bool(message.hasVoted);
    }
    if (message.voteOptionIndex !== 0) {
      writer.uint32(16).int32(message.voteOptionIndex);
    }
    for (const v of message.voteOptionList) {
      UserVoteOptionInfo.encode(v!, writer.uint32(26).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): UserVoteInfo {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseUserVoteInfo();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.hasVoted = reader.bool();
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.voteOptionIndex = reader.int32();
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.voteOptionList.push(UserVoteOptionInfo.decode(reader, reader.uint32()));
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },
};

